      # The +travel_rule.unmatched_deposits+ resource.
      class UnmatchedDeposits < Didit::Resource
        # List unmatched Travel Rule deposits
        #
        # Inbound deposits that are still waiting for the originating VASP's Travel Rule data: their transfer is
        # `AWAITING_COUNTERPARTY`, `NOT_ENOUGH_COUNTERPARTY_DATA` or `COUNTERPARTY_VASP_NOT_FOUND`, no received
        # message is paired with them, and nobody matched them by hand. The rows and the filters are the same as in
        # `GET /v3/travel-rule/transfers/`, newest first, paginated with `limit` (default 50) and `offset`. Pair a
        # deposit with the message the originating VASP sent with `POST
        # /v3/travel-rule/unmatched/{transaction_uuid}/match/`.
        #
        # +GET /v3/travel-rule/unmatched/+
        #
        # @param direction [String] INBOUND, OUTBOUND, or both comma-separated. Case-sensitive.
        # @param status [String] One or more transfer statuses, comma-separated.
        # @param rail [String] One or more of INTERNAL, TRP, GTR, TRUST, VERIFYVASP, SYGNA, EMAIL, TEST_VASP,
        #   comma-separated.
        # @param kind [String] withdrawal, deposit or message, comma-separated.
        # @param currency [String] The transaction's currency, case-insensitive.
        # @param start_date [Date, String] Transfers created on or after this day (UTC), YYYY-MM-DD.
        # @param end_date [Date, String] Transfers created on or before this day (UTC), YYYY-MM-DD.
        # @param counterparty [String] The `id` of a directory entry or Didit network member from GET
        #   /v3/travel-rule/vasps/: your transfers with that counterparty. A value that is not a valid id answers 400.
        # @param limit [Integer] Page size, default 50.
        # @param offset [Integer] Rows to skip.
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Page<Didit::Types::TravelRuleTransferRow>]
        def list(
          direction: OMIT,
          status: OMIT,
          rail: OMIT,
          kind: OMIT,
          currency: OMIT,
          start_date: OMIT,
          end_date: OMIT,
          counterparty: OMIT,
          limit: OMIT,
          offset: OMIT,
          request_options: nil
        )
          @client.request(
            :get,
            "/v3/travel-rule/unmatched/",
            query: {
              "direction" => direction,
              "status" => status,
              "rail" => rail,
              "kind" => kind,
              "currency" => currency,
              "start_date" => start_date,
              "end_date" => end_date,
              "counterparty" => counterparty,
              "limit" => limit,
              "offset" => offset
            },
            page: Types::TravelRuleTransferRow,
            request_options: request_options
          )
        end

        # Match a Travel Rule deposit to a received message
        #
        # Pair an inbound deposit that is still waiting for originator data with the Travel Rule message the
        # originating VASP sent for it. The deposit takes the message's originator data, counterparty VASP and rail,
        # and both transfers record the match on their timelines. `transaction_uuid` is the deposit's `transaction_id`
        # from `GET /v3/travel-rule/unmatched/`. `transaction_id` in the body is the received message's
        # `transaction_id`, from a row of `GET /v3/travel-rule/transfers/?kind=message`; the transfer's own `id` is
        # not found. The message must be for the same asset as the deposit. A deposit or message deleted from the
        # Console answers `404`; one that has already moved on (matched, or no longer waiting) answers `409`.
        #
        # +POST /v3/travel-rule/unmatched/{transaction_uuid}/match/+
        #
        # @param transaction_uuid [String] The `transaction_id` of the unmatched deposit.
        # @param transaction_id [String] The `transaction_id` of the received Travel Rule message (a row with `kind:
        #   message`).
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Types::TravelRuleManualMatchResponse]
        def match(transaction_uuid, transaction_id:, request_options: nil)
          @client.request(
            :post,
            "/v3/travel-rule/unmatched/{transaction_uuid}/match/",
            path_params: { "transaction_uuid" => transaction_uuid },
            body: {
              "transaction_id" => transaction_id
            },
            response: Types::TravelRuleManualMatchResponse,
            request_options: request_options
          )
        end
      end

      # The +travel_rule.wallet_addresses+ resource.
      class WalletAddresses < Didit::Resource
        # Import wallet addresses in bulk
        #
        # Add up to 10,000 wallets to your Travel Rule address book in one call, as JSON or as a CSV file. A wallet
        # can be sent by its address, by the SHA-256 of its lowercased address (`address_hash`) to keep the address
        # private, or both. The import is idempotent: a wallet already in the book is reported as `existing` and left
        # untouched, so the same file can be sent again. Each row is validated on its own, so one bad row never fails
        # the others. A wallet imported by its hash only matches transfers to that address and can be proven with the
        # wallet-ownership widget like any other entry.
        #
        # +POST /v3/travel-rule/wallet-addresses/import/+
        #
        # @param body [Hash, Array<Hash>]
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Types::WalletAddressImportReport]
        def bulk_import(body:, request_options: nil)
          @client.request(
            :post,
            "/v3/travel-rule/wallet-addresses/import/",
            body: body,
            encoding: :auto,
            file_fields: %w[file],
            response: Types::WalletAddressImportReport,
            request_options: request_options
          )
        end

        # Register a wallet address
        #
        # Add an entry to your Travel Rule wallet address book so inbound INTERNAL-rail transfers can resolve against
        # it.
        #
        # +POST /v3/travel-rule/wallet-addresses/+
        #
        # @param address [String] The wallet address. An XRP X-address is stored as its classic address and its tag,
        #   so it matches transfers that name either form.
        # @param chain [String] Chain token for the address, for example `ETH` or `BTC`. When Didit routes or
        #   registers a transfer, it matches address book entries on the wallet address and, when the transfer carries a
        #   chain, on this value too, ignoring case. A transfer's chain is `beneficiary_data.chain`, filled from the
        #   transaction's crypto chain or currency symbol (for example `ETH`) when you do not send it, or the `chain`
        #   o...
        # @param holder_vendor_data [String]
        # @param holder_name [String]
        # @param entity_type [String]
        # @param self_declared [Boolean] Write-only. When true, the entry is created already ownership-verified via a
        #   SELF_DECLARATION proof. Returns 400 when `allow_self_declaration` is off in your Travel Rule settings.
        # @param travel_address [String] Optional. The counterparty VASP's travel address for this wallet, enabling
        #   TRP routing for the assets TRP carries (BTC, ETH, and USDC on a named network). An invalid travel address
        #   returns 400.
        # @param memo [String] Optional. The destination tag or memo that is part of the wallet. XRP: a destination
        #   tag, a whole number from 0 to 4294967295 (a JSON number is accepted). XLM: a text memo of up to 28 bytes, a
        #   64-bit id or a 32-byte hash in hex. EOS: up to 256 bytes. ATOM: up to 256 characters. HBAR: up to 100 bytes.
        #   Bitcoin, EVM, Solana, Tron, Litecoin, Bitcoin Cash, Dogecoin and Lightning wallets take no memo:...
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Types::WalletAddressEntry]
        def create(
          address:,
          chain: OMIT,
          holder_vendor_data: OMIT,
          holder_name: OMIT,
          entity_type: OMIT,
          self_declared: OMIT,
          travel_address: OMIT,
          memo: OMIT,
          request_options: nil
        )
          @client.request(
            :post,
            "/v3/travel-rule/wallet-addresses/",
            body: {
              "address" => address,
              "chain" => chain,
              "holder_vendor_data" => holder_vendor_data,
              "holder_name" => holder_name,
              "entity_type" => entity_type,
              "self_declared" => self_declared,
              "travel_address" => travel_address,
              "memo" => memo
            },
            response: Types::WalletAddressEntry,
            request_options: request_options
          )
        end

        # Delete a wallet address
        #
        # Deletes the entry together with its ownership proofs and the screenshots they stored. It stops matching new
        # transfers immediately and the address is freed up for re-registration. Transfers that already used the
        # wallet keep their own record of it and read the same. Deletion is irreversible.
        #
        # +DELETE /v3/travel-rule/wallet-addresses/{entry_uuid}/+
        #
        # @param entry_uuid [String]
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [nil]
        def delete(entry_uuid, request_options: nil)
          @client.request(
            :delete,
            "/v3/travel-rule/wallet-addresses/{entry_uuid}/",
            path_params: { "entry_uuid" => entry_uuid },
            request_options: request_options
          )
        end

        # List wallet address book entries
        #
        # Paginated list of your application's Travel Rule wallet address book, newest first.
        #
        # +GET /v3/travel-rule/wallet-addresses/+
        #
        # @param limit [Integer]
        # @param offset [Integer]
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Page<Didit::Types::WalletAddressEntry>]
        def list(limit: OMIT, offset: OMIT, request_options: nil)
          @client.request(
            :get,
            "/v3/travel-rule/wallet-addresses/",
            query: {
              "limit" => limit,
              "offset" => offset
            },
            page: Types::WalletAddressEntry,
            request_options: request_options
          )
        end

        # List the transfers that used a wallet address
        #
        # Paginated list of your Travel Rule transfers whose originator or beneficiary wallet is this address book
        # entry, newest first. The endpoint answers 404 once the entry is deleted.
        #
        # +GET /v3/travel-rule/wallet-addresses/{entry_uuid}/transfers/+
        #
        # @param entry_uuid [String]
        # @param limit [Integer]
        # @param offset [Integer]
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Page<Didit::Types::TravelRuleWalletTransfer>]
        def list_transfers(entry_uuid, limit: OMIT, offset: OMIT, request_options: nil)
          @client.request(
            :get,
            "/v3/travel-rule/wallet-addresses/{entry_uuid}/transfers/",
            path_params: { "entry_uuid" => entry_uuid },
            query: {
              "limit" => limit,
              "offset" => offset
            },
            page: Types::TravelRuleWalletTransfer,
            request_options: request_options
          )
        end

        # Look up a wallet address
        #
        # Checks one exact address, chain and memo against your own wallet address book and then against wallets
        # proven by other Didit Travel Rule participants. It never screens the wallet, never sends a message and never
        # returns holder data from another application. `directory_checked` is always `false`: the lookup does not
        # search a public directory, so `none` means the wallet is neither in your book nor proven on Didit, not that
        # it is unknown elsewhere.
        #
        # +GET /v3/travel-rule/wallet-addresses/lookup/+
        #
        # @param address [String] The wallet address.
        # @param chain [String] Chain token, for example `ETH`, `BTC` or `SOL`.
        # @param memo [String] Destination tag or memo, for chains that use one.
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Types::TravelRuleWalletLookup]
        def lookup(address:, chain:, memo: OMIT, request_options: nil)
          @client.request(
            :get,
            "/v3/travel-rule/wallet-addresses/lookup/",
            query: {
              "address" => address,
              "chain" => chain,
              "memo" => memo
            },
            response: Types::TravelRuleWalletLookup,
            request_options: request_options
          )
        end

        # Update wallet address holder metadata
        #
        # Partial update of holder_name, holder_vendor_data, entity_type, and travel_address. Setting travel_address
        # attaches a TRP routing address to the entry; invalid values are rejected with 400. The response returns the
        # updated entry: its label, owner type, receiving travel address and ownership proof summary, with the
        # writable fields.
        #
        # +PATCH /v3/travel-rule/wallet-addresses/{entry_uuid}/+
        #
        # @param entry_uuid [String]
        # @param holder_name [String]
        # @param holder_vendor_data [String]
        # @param entity_type [String]
        # @param travel_address [String]
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Types::WalletAddressEntryUpdateResponse]
        def update(
          entry_uuid,
          holder_name: OMIT,
          holder_vendor_data: OMIT,
          entity_type: OMIT,
          travel_address: OMIT,
          request_options: nil
        )
          @client.request(
            :patch,
            "/v3/travel-rule/wallet-addresses/{entry_uuid}/",
            path_params: { "entry_uuid" => entry_uuid },
            body: {
              "holder_name" => holder_name,
              "holder_vendor_data" => holder_vendor_data,
              "entity_type" => entity_type,
              "travel_address" => travel_address
            },
            response: Types::WalletAddressEntryUpdateResponse,
            request_options: request_options
          )
        end
      end

      # The +travel_rule.wallet_proofs+ resource.
      class WalletProofs < Didit::Resource
        # Approve or reject a screenshot wallet proof
        #
        # Decide a screenshot proof from your review queue. approve verifies the proof and the address book entry and
        # applies the ownership to the transfer the widget session was minted for, exactly as a verified signature
        # does. A screenshot never confirms a transfer that another Didit customer sent over the INTERNAL rail: that
        # takes a signed message or a test deposit. reject closes the proof as REJECTED with failure_reason
        # REVIEW_REJECTED; the end user can start a new proof from the widget. The note is kept with the proof.
        #
        # +POST /v3/travel-rule/wallet-proofs/{proof_uuid}/decision/+
        #
        # @param proof_uuid [String] proof_id from the review queue.
        # @param decision [String]
        # @param note [String] Optional. Kept with the proof and returned as review_note.
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Types::TravelRuleWalletProofReview]
        def decide(proof_uuid, decision:, note: OMIT, request_options: nil)
          @client.request(
            :post,
            "/v3/travel-rule/wallet-proofs/{proof_uuid}/decision/",
            path_params: { "proof_uuid" => proof_uuid },
            body: {
              "decision" => decision,
              "note" => note
            },
            response: Types::TravelRuleWalletProofReview,
            request_options: request_options
          )
        end

        # List screenshot wallet proofs to review
        #
        # Your review queue for screenshot wallet-ownership proofs. A screenshot is the one proof Didit cannot check
        # itself: once the end user uploads it from the widget it waits PENDING until you approve or reject it with
        # POST /v3/travel-rule/wallet-proofs/{proof_uuid}/decision/. Oldest first, so the queue is worked from the
        # proof that has waited longest. Only uploaded screenshots appear, never a proof whose end user has not
        # uploaded a file yet, and never one on a wallet you deleted from your address book (Didit closes those as
        # OWNERSHIP_CHANGED).
        #
        # +GET /v3/travel-rule/wallet-proofs/+
        #
        # @param status [String] Which proofs to list. Defaults to PENDING, the ones still to decide.
        # @param limit [Integer]
        # @param offset [Integer]
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Page<Didit::Types::TravelRuleWalletProofReview>]
        def list(status: OMIT, limit: OMIT, offset: OMIT, request_options: nil)
          @client.request(
            :get,
            "/v3/travel-rule/wallet-proofs/",
            query: {
              "status" => status,
              "limit" => limit,
              "offset" => offset
            },
            page: Types::TravelRuleWalletProofReview,
            request_options: request_options
          )
        end
      end

      # The +travel_rule.workspace+ resource.
      class Workspace < Didit::Resource
        # Claim a directory entry
        #
        # Claims the directory entry this workspace is. When the work email is at a domain the entry lists, the claim
        # is proved and applies at once: the VASP profile and Travel Rule settings are filled from the entry and
        # Travel Rule is turned on, so the next transfer to it routes over the Didit network. Otherwise the claim
        # waits for review (`pending_review`).
        #
        # +POST /v3/travel-rule/workspace/claim/+
        #
        # @param vasp_id [String] The directory entry this workspace is. Read ids from `GET /v3/travel-rule/vasps/`.
        # @param licence [String] Optional licence or registration reference, up to 255 characters; empty clears it.
        #   Omission preserves it for the same directory entry and clears it when claiming a different entry. Applied to
        #   the VASP profile only when the claim is granted.
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Types::TravelRuleWorkspace]
        def claim(vasp_id:, licence: OMIT, request_options: nil)
          @client.request(
            :post,
            "/v3/travel-rule/workspace/claim/",
            body: {
              "vasp_id" => vasp_id,
              "licence" => licence
            },
            response: Types::TravelRuleWorkspace,
            request_options: request_options
          )
        end

        # Confirm the domain verification code
        #
        # Spends the emailed code and marks the email domain verified.
        #
        # +POST /v3/travel-rule/workspace/domain/confirm/+
        #
        # @param code [String]
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Types::TravelRuleWorkspace]
        def confirm_domain(code:, request_options: nil)
          @client.request(
            :post,
            "/v3/travel-rule/workspace/domain/confirm/",
            body: {
              "code" => code
            },
            response: Types::TravelRuleWorkspace,
            request_options: request_options
          )
        end

        # Enable outbound billing
        #
        # Turns outbound Travel Rule billing on for the workspace. Receiving stays free. This cannot be turned back
        # off through the API: contact Didit support.
        #
        # +POST /v3/travel-rule/workspace/billing/+
        #
        # @param enabled [Boolean] Only `true` is accepted: outbound billing cannot be turned back off through the
        #   API.
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Types::TravelRuleWorkspace]
        def enable_billing(enabled: OMIT, request_options: nil)
          @client.request(
            :post,
            "/v3/travel-rule/workspace/billing/",
            body: {
              "enabled" => enabled
            },
            response: Types::TravelRuleWorkspace,
            request_options: request_options
          )
        end

        # Get the free Travel Rule workspace
        #
        # Reads the free workspace of an application that joined free: directory claim, domain proof, billing and
        # Didit network listing.
        #
        # +GET /v3/travel-rule/workspace/+
        #
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Types::TravelRuleWorkspace]
        def get(request_options: nil)
          @client.request(
            :get,
            "/v3/travel-rule/workspace/",
            response: Types::TravelRuleWorkspace,
            request_options: request_options
          )
        end

        # Email a domain verification code
        #
        # Emails a single-use code to the workspace's work address to prove it controls the email domain. Throttled,
        # and a limited number of wrong attempts is accepted per code. Also returns the TXT record for the DNS
        # alternative.
        #
        # +POST /v3/travel-rule/workspace/domain/code/+
        #
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Types::TravelRuleWorkspaceDomainCodeResponse]
        def send_domain_code(request_options: nil)
          @client.request(
            :post,
            "/v3/travel-rule/workspace/domain/code/",
            response: Types::TravelRuleWorkspaceDomainCodeResponse,
            request_options: request_options
          )
        end

        # Verify the domain from its TXT record
        #
        # Checks for the `didit-tr-verify.<domain>` TXT record returned by the code endpoint and marks the domain
        # verified when it matches. One of the two proofs, the emailed code or the TXT record, is enough.
        #
        # +POST /v3/travel-rule/workspace/domain/dns/+
        #
        # @param request_options [Hash, nil] :timeout, :max_retries, :extra_headers, :extra_query, :extra_body
        # @return [Didit::Types::TravelRuleWorkspace]
        def verify_domain_dns(request_options: nil)
          @client.request(
            :post,
            "/v3/travel-rule/workspace/domain/dns/",
            response: Types::TravelRuleWorkspace,
            request_options: request_options
          )
        end
      end
    end
  end
end
